#!/usr/bin/env python3
"""
Test script for Keyboard Macro Recorder

This script tests the basic functionality of the keyboard macro recorder
by simulating keyboard input and verifying the output JSON format.
"""

import json
import time
import os
import sys

def test_json_format():
    """Test that the generated JSON format is valid TurboMacro format."""
    
    # Sample JSON that should be generated by the recorder
    sample_macro = [
        {
            "Action": "button-A",
            "HoldMs": "150 ms",
            "ReleaseMs": "50 ms"
        },
        {
            "Action": "left-joystick",
            "MoveDirectionX": 128,
            "MoveDirectionY": 0,
            "HoldMs": "2000 ms",
            "ReleaseMs": "1000 ms"
        },
        {
            "Action": "wait",
            "WaitMs": "500 ms"
        }
    ]
    
    # Test JSON serialization
    try:
        json_string = json.dumps(sample_macro, indent=2)
        print("✓ JSON serialization works")
        
        # Test JSON deserialization
        parsed = json.loads(json_string)
        print("✓ JSON deserialization works")
        
        # Test structure validation
        for action in parsed:
            if "Action" not in action:
                raise ValueError("Missing 'Action' field")
            
            action_type = action["Action"]
            if action_type.startswith("button-"):
                if "HoldMs" not in action:
                    raise ValueError(f"Button action missing 'HoldMs': {action_type}")
                if "ReleaseMs" not in action:
                    raise ValueError(f"Button action missing 'ReleaseMs': {action_type}")
            elif action_type in ["left-joystick", "right-joystick"]:
                if "MoveDirectionX" not in action:
                    raise ValueError(f"Joystick action missing 'MoveDirectionX': {action_type}")
                if "MoveDirectionY" not in action:
                    raise ValueError(f"Joystick action missing 'MoveDirectionY': {action_type}")
            elif action_type == "wait":
                if "WaitMs" not in action:
                    raise ValueError("Wait action missing 'WaitMs'")
        
        print("✓ JSON structure validation passed")
        return True
        
    except Exception as e:
        print(f"✗ JSON test failed: {e}")
        return False

