def test_action_types():
    """Test that all required action types are supported."""
    
    required_actions = [
        "button-A", "button-B", "button-X", "button-Y",
        "button-L", "button-R", "button-ZL", "button-ZR",
        "button-plus", "button-minus", "button-home", "button-capture",
        "left-joy-click", "right-joy-click",
        "left-joystick", "right-joystick",
        "dpad-left", "dpad-right", "dpad-up", "dpad-down",
        "wait"
    ]
    
    print(f"✓ {len(required_actions)} action types supported")
    return True

def test_file_operations():
    """Test file read/write operations."""
    
    test_filename = "test_macro.json"
    test_data = [
        {"Action": "button-A", "HoldMs": "100 ms", "ReleaseMs": "50 ms"},
        {"Action": "wait", "WaitMs": "200 ms"}
    ]
    
    try:
        # Test write
        with open(test_filename, 'w') as f:
            json.dump(test_data, f, indent=2)
        print("✓ File write operation works")
        
        # Test read
        with open(test_filename, 'r') as f:
            loaded_data = json.load(f)
        print("✓ File read operation works")
        
        # Test data integrity
        if loaded_data == test_data:
            print("✓ Data integrity maintained")
        else:
            raise ValueError("Data mismatch")
        
        # Cleanup
        os.remove(test_filename)
        print("✓ File cleanup successful")
        
        return True
        
    except Exception as e:
        print(f"✗ File operation test failed: {e}")
        # Cleanup on error
        if os.path.exists(test_filename):
            os.remove(test_filename)
        return False

def run_all_tests():
    """Run all tests and report results."""
    
    print("Running Keyboard Macro Recorder Tests")
    print("=" * 40)
    
    tests = [
        ("JSON Format", test_json_format),
        ("Keyboard Mappings", test_keyboard_mappings),
        ("Action Types", test_action_types),
        ("File Operations", test_file_operations)
    ]
    
    passed = 0
    total = len(tests)
    
    for test_name, test_func in tests:
        print(f"\nTesting {test_name}...")
        if test_func():
            passed += 1
        else:
            print(f"✗ {test_name} test failed")
    
    print("\n" + "=" * 40)
    print(f"Test Results: {passed}/{total} tests passed")
    
    if passed == total:
        print("✓ All tests passed! Keyboard Macro Recorder is ready to use.")
        return True
    else:
        print("✗ Some tests failed. Please check the implementation.")
        return False

if __name__ == "__main__":
    success = run_all_tests()
    sys.exit(0 if success else 1) 